// 高校受験 理科（formulas-koko-rika.ts）以前からある項目 14〜26番目の動く図解スライド。
// キーは項目の label（買い切りの識別キーと同じ）。「なぜ？」の連鎖で、根っこまでたどる。
import type { DiagramElement, DiagramFigure } from './figures';
import { C, FILL, bx, lb, ar, ln, ci, pg, show, fresh, flow } from './diagram-kit';

type Col = 'red' | 'blue' | 'green' | 'main' | 'purple' | 'gray';
const CF: Record<Col, [string, string]> = {
  red: [C.red, FILL.red],
  blue: [C.blue, FILL.blue],
  green: [C.green, FILL.green],
  main: [C.main, FILL.warm],
  purple: [C.purple, FILL.purple],
  gray: [C.gray, FILL.gray],
};
/** 1枚のスライド。上半分に図、下の帯に結論（big）とひとこと（small）。 */
const sl = (note: string, pic: DiagramElement[], big?: string, small?: string, col: Col = 'blue') => ({
  note,
  add: fresh(
    ...pic,
    ...(big ? [bx(20, 166, 280, 34, big, CF[col][0], CF[col][1], 15)] : []),
    ...(small ? [lb(160, 218, small, 12, C.gray, 'middle')] : []),
  ),
});
const dot = (x: number, y: number, r = 4, col: string = C.blue): DiagramElement => ci(x, y, r, undefined, col, col);
const wave = (x0: number, y0: number, w: number, amp: number, cycles: number, col: string = C.blue): DiagramElement[] => {
  const n = 32;
  const out: DiagramElement[] = [];
  for (let i = 0; i < n; i++) {
    const xa = x0 + (w * i) / n, xb = x0 + (w * (i + 1)) / n;
    const ya = y0 - amp * Math.sin((2 * Math.PI * cycles * i) / n), yb = y0 - amp * Math.sin((2 * Math.PI * cycles * (i + 1)) / n);
    out.push(ln(xa, ya, xb, yb, col, false, 2.2));
  }
  return out;
};
const axes = (ox: number, oy: number, xe: number, yt: number, xl: string, yl: string): DiagramElement[] => [
  ln(ox, oy, xe, oy, C.ink, false, 2),
  ln(ox, oy, ox, yt, C.ink, false, 2),
  lb(xe, oy + 10, xl, 10, C.gray, 'end'),
  lb(ox + 4, yt - 6, yl, 10, C.gray, 'start'),
];

// ══ 回路の部品 ══
const battery = (x: number, y: number, txt: string): DiagramElement => bx(x, y, 36, 26, txt, C.red, FILL.red, 11);
const meter = (x: number, y: number, ch: string, col: string = C.purple): DiagramElement => ci(x, y, 11, ch, col, FILL.purple, 12);
/** 直列回路：外わく + 上に2つの抵抗 */
const serial = (a = '10Ω', b = '20Ω', v = '9V'): DiagramElement[] => [
  ln(40, 30, 280, 30, C.ink, false, 2), ln(40, 120, 280, 120, C.ink, false, 2),
  ln(40, 30, 40, 120, C.ink, false, 2), ln(280, 30, 280, 120, C.ink, false, 2),
  battery(22, 62, v), bx(90, 17, 60, 26, a, C.main, FILL.warm, 12), bx(190, 17, 60, 26, b, C.blue, FILL.blue, 12),
];
/** 並列回路：2本の枝 */
const parallel = (a: string, b: string, v: string): DiagramElement[] => [
  ln(40, 25, 230, 25, C.ink, false, 2), ln(40, 125, 230, 125, C.ink, false, 2), ln(40, 25, 40, 125, C.ink, false, 2),
  ln(130, 25, 130, 125, C.ink, false, 2), ln(230, 25, 230, 125, C.ink, false, 2),
  battery(22, 62, v), bx(105, 62, 50, 26, a, C.main, FILL.warm, 12), bx(205, 62, 50, 26, b, C.blue, FILL.blue, 12),
];

