// ══ 20. 右ねじの法則 ══
/** 同心円（外側から内側へ描く）。dir: 上端での向き */
const rings = (cx: number, cy: number, rs: number[], center?: DiagramElement, dirTop?: 'l' | 'r'): DiagramElement[] => {
  const out: DiagramElement[] = [];
  [...rs].sort((a, b) => b - a).forEach((r) => out.push(ci(cx, cy, r, undefined, C.blue, FILL.blue)));
  if (dirTop) {
    const r = Math.max(...rs);
    out.push(dirTop === 'l' ? ar(cx + 9, cy - r, cx - 9, cy - r, C.red) : ar(cx - 9, cy - r, cx + 9, cy - r, C.red));
  }
  if (center) out.push(center);
  return out;
};
